function extractPlaceholders(text) {
  const matches = new Set();
  const regex = /\{([a-zA-Z0-9_-]+)\}/g;
  let match;
  while ((match = regex.exec(text)) !== null) {
    matches.add(match[1]);
  }
  return [...matches];
}

function isReplied(value) {
  if (value === true) return true;
  if (value === false || value == null) return false;
  return ['true', '1', 'yes', 'y'].includes(String(value).trim().toLowerCase());
}

function simpleHash(input) {
  let hash = 2166136261;
  const str = String(input);
  for (let index = 0; index < str.length; index++) {
    hash ^= str.charCodeAt(index);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function tokenForEmail(mailId, email) {
  return `${mailId}-${simpleHash(String(email).trim().toLowerCase())}`;
}

const senderName = 'Brian | Tookio Solutions';
const subject = 'ERPNext for your Manufacturing Workflow';
const mailId = 'erpnext_mfg_01';
const logoUrl = 'https://erp.tookio.co.ke//files/tookio-high-resolution-logo.png';
const sequence = [
  { send_on_day: 0, message: 'Hi {name},<br /><br />I hope you\'re having a good week.<br /><br />I consult for a few manufacturing setups around Kenya, helping them migrate off messy spreadsheets and onto centralized systems.<br /><br />I\'ve been following {company}, and I was curious if you are currently running your production planning and inventory on a unified system, or if you are still piecing things together across different software?<br /><br />At Tookio Solutions, we build out custom setups using ERPNext. We handle the heavy lifting of building the exact integrations and custom workflows needed for your specific company.<br /><br />I would love to hear back from you on this if you\'re exploring better ways to streamline your operations.<br /><br />Best,<br /><br />Brian Wachira<br />Consultant, Tookio Solutions<br />' },
  { send_on_day: 3, message: 'Hi {name},<br /><br />Just bumping this to the top of your inbox. I know things get busy at {company}.<br /><br />If you\'re open to it, I\'d still love to get your thoughts on how a unified ERPNext system could handle your custom workflows better than disjointed software.<br /><br />Let me know if you have a few minutes next week.<br /><br />Best,<br /><br />Brian Wachira<br />' },
  { send_on_day: 8, message: 'Hi {name},<br /><br />I completely understand if streamlining your ERP isn\'t a priority for {company} right now.<br /><br />I\'ll stop reaching out, but if you ever find yourselves outgrowing your current inventory and production setups, feel free to drop me a note.<br /><br />Wishing you the best!<br /><br />Brian Wachira<br />Tookio Solutions<br />' }
];
const placeholderNames = [...new Set(sequence.flatMap(step => extractPlaceholders(step.message)))];
const now = DateTime.now();
const results = [];

for (const item of $input.all()) {
  const row = item.json;
  const email = row.email;
  if (!email) continue;
  if (isReplied(row.replied)) continue;

  let firstEmailed = row.first_emailed ? String(row.first_emailed) : '';
  let seqIndex = Number.isFinite(Number(row.seq_number)) ? Number(row.seq_number) : -1;
  let shouldSend = false;

  if (!firstEmailed) {
    seqIndex = 0;
    firstEmailed = now.toFormat('yyyy-MM-dd');
    shouldSend = true;
  } else {
    const nextIndex = seqIndex + 1;
    if (nextIndex < sequence.length) {
      const startedAt = DateTime.fromISO(firstEmailed);
      if (startedAt.isValid) {
        const daysSinceStart = now.diff(startedAt, 'days').days;
        if (daysSinceStart >= sequence[nextIndex].send_on_day) {
          seqIndex = nextIndex;
          shouldSend = true;
        }
      }
    }
  }

  if (!shouldSend) continue;

  const placeholders = {};
  for (const placeholderName of placeholderNames) {
    if (!(placeholderName in row)) {
      throw new Error(`Missing required sheet column: ${placeholderName}`);
    }
    placeholders[placeholderName] = row[placeholderName];
  }

  const campaignToken = tokenForEmail(mailId, email);
  results.push({
    json: {
      ...row,
      to_email: email,
      subject: subject,
      sender_name: senderName,
      mail_id: mailId,
      mail_seq: seqIndex,
      message_template: sequence[seqIndex].message,
      placeholders,
      campaign_token: campaignToken,
      logo_url: logoUrl,
      first_emailed: firstEmailed,
      last_emailed: now.toFormat('yyyy-MM-dd HH:mm:ss'),
      seq_number: String(seqIndex)
    }
  });
}

return results;

function extractPlaceholders(text) {
  const matches = new Set();
  const regex = /\{([a-zA-Z0-9_-]+)\}/g;
  let match;
  while ((match = regex.exec(text)) !== null) {
    matches.add(match[1]);
  }
  return [...matches];
}

const placeholders = item.json.placeholders || {};
let html = item.json.message_template;

for (const placeholderName of extractPlaceholders(html)) {
  const value = placeholderName in placeholders ? String(placeholders[placeholderName]) : '';
  html = html.replace(new RegExp(`\\{${placeholderName}\\}`, 'g'), value);
}

const logoHtml = item.json.logo_url ? `<br /><br /><img src="${item.json.logo_url}" alt="Tookio Solutions" style="max-width:180px;height:auto;" />` : '';
item.json.message = ['<span data-cam=', item.json.campaign_token, ' data-seq=', item.json.mail_seq, ' data-ph=', encodeURIComponent(JSON.stringify(placeholders)), '></span>', html, logoHtml].join('');
return item;

function asText(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(asText).join(' ');
  if (typeof value === 'object') {
    return value.text || value.value || value.address || value.name || JSON.stringify(value);
  }
  return String(value);
}

function extractEmail(value) {
  const match = asText(value).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return match ? match[0].toLowerCase() : '';
}

function tokenFromSubject(subject) {
  const match = String(subject || '').match(/\[([a-zA-Z0-9_-]+)\]/);
  return match ? match[1] : '';
}

function tokenFromBody(text) {
  const match = String(text || '').match(/data-cam=['"]([^'"]+)['"]/i);
  return match ? match[1] : '';
}

for (const item of $input.all()) {
  const message = item.json;
  const subject = asText(message.subject || message.headers?.subject || message.envelope?.subject || '');
  const fromEmail = extractEmail(message.from || message.From || message.sender || message.replyTo || message.headers?.from || message.envelope?.from || '');
  const html = asText(message.html || message.body?.html || message.message?.html || message.payload?.body?.data || '');
  const text = asText(message.text || message.body?.text || message.message?.text || message.snippet || '');
  const token = tokenFromSubject(subject) || tokenFromBody(html) || tokenFromBody(text);

  item.json = {
    ...message,
    parsed_subject: subject,
    from_email: fromEmail,
    reply_html: html,
    reply_text: text,
    campaign_token: token
  };
}

return $input.all();

