const mailId = 'erpnext_mfg_01';
const reply = $('Parse IMAP reply').first().json;
const replyEmail = String(reply.from_email || '').trim().toLowerCase();
const replyToken = String(reply.campaign_token || '').trim();

for (const item of $input.all()) {
  const row = item.json;
  const email = String(row.email || '').trim().toLowerCase();
  if (!email) continue;

  const expectedToken = tokenForEmail(mailId, email);
  const tokenMatches = replyToken && replyToken === expectedToken;
  const emailMatches = replyEmail && replyEmail === email;

  if (tokenMatches || emailMatches) {
    item.json = {
      ...row,
      replied: true,
      reply_subject: reply.parsed_subject || '',
      reply_from_email: replyEmail || '',
      reply_token: replyToken || '',
      reply_body: reply.reply_text || reply.reply_html || ''
    };
    return item;
  }
}

throw new Error(`No matching row found for reply from ${replyEmail || 'unknown sender'}`);
